import * as Schema from "effect/Schema";
import { HttpApiEndpoint, HttpApiGroup, HttpApiSchema } from "effect/http-api";

import {
  InvalidPollContent,
  InvalidResponse,
  InvalidTransition,
  NotStudent,
  PollNotActive,
  PollNotDraft,
  PollNotFound,
  SessionNotFound,
} from "./errors.ts";
import { CurrentUserMiddleware } from "./middleware.ts";
import { Ulid } from "./ulid.ts";

export const maxOptions = 10;
export const maxWords = 10;
export const maxWordLength = 30;

export const PollType = Schema.Literals(["choice", "words", "scale"]);

export type PollType = typeof PollType.Type;

export const PollStatus = Schema.Literals(["draft", "active", "closed"]);

export type PollStatus = typeof PollStatus.Type;

export const VisiblePollStatus = Schema.Literals(["active", "closed"]);

export type VisiblePollStatus = typeof VisiblePollStatus.Type;

const Text = Schema.String.check(Schema.isMinLength(1));

export const PollOptions = Schema.Array(Text).check(
  Schema.isMinLength(2),
  Schema.isMaxLength(maxOptions),
);

const pollFields = {
  sessionId: Ulid,
  type: PollType,
  prompt: Text,
  options: Schema.optional(PollOptions),
  scaleMinLabel: Schema.optional(Schema.String),
  scaleMaxLabel: Schema.optional(Schema.String),
};

export const PollDraft = Schema.Struct(pollFields);

export type PollDraft = typeof PollDraft.Type;

export const PollChange = Schema.Struct({
  prompt: Schema.optionalKey(Text),
  options: Schema.optionalKey(PollOptions),
  scaleMinLabel: Schema.optionalKey(Schema.String),
  scaleMaxLabel: Schema.optionalKey(Schema.String),
  status: Schema.optionalKey(VisiblePollStatus),
});

export type PollChange = typeof PollChange.Type;

export const ResponseValue = Schema.Union([
  Schema.Struct({ choice: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)) }),
  Schema.Struct({ scale: Schema.Int.check(Schema.isBetween({ minimum: 1, maximum: 5 })) }),
  Schema.Struct({
    words: Schema.Array(
      Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(maxWordLength)),
    ).check(Schema.isMinLength(1), Schema.isMaxLength(maxWords)),
  }),
]);

export type ResponseValue = typeof ResponseValue.Type;

export const PollResults = Schema.Struct({
  count: Schema.Int,
  choice: Schema.optionalKey(Schema.Array(Schema.Int)),
  scale: Schema.optionalKey(
    Schema.Array(Schema.Int).check(Schema.isMinLength(5), Schema.isMaxLength(5)),
  ),
  words: Schema.optionalKey(
    Schema.Array(Schema.Struct({ word: Schema.String, count: Schema.Int })),
  ),
});

export type PollResults = typeof PollResults.Type;

export const Poll = Schema.Struct({
  ...pollFields,
  id: Ulid,
  status: VisiblePollStatus,
  myResponse: Schema.NullOr(ResponseValue),
  results: Schema.NullOr(PollResults),
});

export type Poll = typeof Poll.Type;

export const AdminPoll = Schema.Struct({
  ...pollFields,
  id: Ulid,
  status: PollStatus,
  results: PollResults,
});

export type AdminPoll = typeof AdminPoll.Type;

export class PollsGroup extends HttpApiGroup.make("polls")
  .add(
    HttpApiEndpoint.get("list", "/polls", {
      query: {
        sessionId: Schema.optionalKey(Ulid),
        status: Schema.optionalKey(VisiblePollStatus),
      },
      success: Schema.Array(Poll),
      error: SessionNotFound,
    }),
    HttpApiEndpoint.patch("vote", "/polls/:id", {
      params: { id: Ulid },
      payload: Schema.Struct({ myResponse: ResponseValue }),
      success: Poll,
      error: [PollNotFound, PollNotActive, InvalidResponse, NotStudent],
    }),
  )
  .middleware(CurrentUserMiddleware) {}

export class AdminPollsGroup extends HttpApiGroup.make("adminPolls")
  .add(
    HttpApiEndpoint.get("list", "/admin/polls", {
      query: { sessionId: Ulid },
      success: Schema.Array(AdminPoll),
      error: SessionNotFound,
    }),
    HttpApiEndpoint.post("create", "/admin/polls", {
      payload: PollDraft,
      success: AdminPoll.pipe(HttpApiSchema.status(201)),
      error: [SessionNotFound, InvalidPollContent],
    }),
    HttpApiEndpoint.patch("update", "/admin/polls/:id", {
      params: { id: Ulid },
      payload: PollChange,
      success: AdminPoll,
      error: [PollNotFound, PollNotDraft, InvalidTransition, InvalidPollContent],
    }),
    HttpApiEndpoint.delete("delete", "/admin/polls/:id", {
      params: { id: Ulid },
      success: HttpApiSchema.NoContent,
      error: PollNotFound,
    }),
  )
  .middleware(CurrentUserMiddleware) {}

import {
  InvalidPollContent,
  InvalidResponse,
  InvalidTransition,
  NotStudent,
  PollNotActive,
  PollNotDraft,
  PollNotFound,
  type SessionNotFound,
} from "@kurasu/contract/errors";
import {
  type AdminPoll,
  type Poll,
  type PollChange,
  type PollDraft,
  type PollStatus,
  type ResponseValue,
  type VisiblePollStatus,
} from "@kurasu/contract/polls";
import type { Ulid } from "@kurasu/contract/ulid";
import type { User } from "@kurasu/contract/user";
import * as Context from "effect/Context";
import * as Crypto from "effect/Crypto";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";

import { Changelog } from "../changelog/changelog.ts";
import { Classroom } from "../classroom.ts";
import { SessionsStore } from "../sessions/sessions-store.ts";
import { existingSession, visibleSession } from "../sessions/visible-session.ts";
import { fitsType } from "./fits-type.ts";
import { PollsStore, type StoredPoll } from "./polls-store.ts";
import { noResponses, ResponsesStore } from "./responses-store.ts";
import { fitsPoll, tally } from "./tally.ts";

export interface StudentPollFilter {
  readonly sessionId?: Ulid | undefined;
  readonly status?: VisiblePollStatus | undefined;
}

const transitions: ReadonlyArray<readonly [PollStatus, PollStatus]> = [
  ["draft", "active"],
  ["active", "closed"],
];

const isContentChange = (change: PollChange) =>
  change.prompt != null ||
  change.options != null ||
  change.scaleMinLabel != null ||
  change.scaleMaxLabel != null;

// Drafts never reach the student, so a stored status they see is active or
// closed.
const visibleStatus = (status: PollStatus): VisiblePollStatus =>
  status === "closed" ? "closed" : "active";

// The polls as each side sees them. The student sees the active and closed
// polls of enabled sessions, with their own vote, and the results once they
// voted or the poll closed. The teacher sees every poll not deleted with its
// results, and moves a poll only from draft to active and from active to
// closed; only a draft's content changes.
export class Polls extends Context.Service<
  Polls,
  {
    readonly listForStudent: (
      viewer: User,
      filter: StudentPollFilter,
    ) => Effect.Effect<ReadonlyArray<Poll>, SessionNotFound>;
    readonly vote: (
      viewer: User,
      id: Ulid,
      response: ResponseValue,
    ) => Effect.Effect<Poll, NotStudent | PollNotFound | PollNotActive | InvalidResponse>;
    readonly listForTeacher: (
      sessionId: Ulid,
    ) => Effect.Effect<ReadonlyArray<AdminPoll>, SessionNotFound>;
    readonly create: (
      draft: PollDraft,
    ) => Effect.Effect<AdminPoll, SessionNotFound | InvalidPollContent>;
    readonly update: (
      id: Ulid,
      change: PollChange,
    ) => Effect.Effect<
      AdminPoll,
      PollNotFound | PollNotDraft | InvalidTransition | InvalidPollContent
    >;
    readonly remove: (id: Ulid) => Effect.Effect<void, PollNotFound>;
  }
>()("kurasu/Polls") {
  static readonly layer = Layer.effect(
    Polls,
    Effect.gen(function* () {
      const store = yield* PollsStore;
      const responses = yield* ResponsesStore;
      const sessions = yield* SessionsStore;
      const classroom = yield* Classroom;
      const changelog = yield* Changelog;
      const crypto = yield* Crypto.Crypto;

      const forStudent = (viewer: User, polls: ReadonlyArray<StoredPoll>) =>
        Effect.gen(function* () {
          const mine = new Map(
            (yield* responses.list({
              where: { userId: viewer.id, pollId: polls.map((poll) => poll.id) },
            })).map((response) => [response.pollId, response.value]),
          );

          const shown = polls.flatMap((poll) =>
            poll.status === "closed" || mine.has(poll.id) ? [poll.id] : [],
          );

          const counts = yield* responses.counts(shown);

          return polls.map((poll): Poll => ({
            ...poll,
            status: visibleStatus(poll.status),
            myResponse: mine.get(poll.id) ?? null,
            results: shown.includes(poll.id)
              ? tally(poll, counts.get(poll.id) ?? noResponses)
              : null,
          }));
        });

      const forTeacher = (polls: ReadonlyArray<StoredPoll>) =>
        Effect.map(responses.counts(polls.map((poll) => poll.id)), (counts) =>
          polls.map((poll): AdminPoll => ({
            ...poll,
            results: tally(poll, counts.get(poll.id) ?? noResponses),
          })),
        );

      const findPoll = (id: Ulid) =>
        Effect.flatMap(store.get(id), (poll) =>
          Effect.fromOption(poll).pipe(Effect.mapError(() => new PollNotFound())),
        );

      const notifyPolls = (poll: StoredPoll) => classroom.notify(poll.sessionId, "polls");

      return Polls.of({
        listForStudent: Effect.fn("Polls.listForStudent")(function* (viewer, filter) {
          const sessionIds =
            filter.sessionId == null
              ? (yield* sessions.listEnabled()).map((session) => session.id)
              : [(yield* visibleSession(sessions, filter.sessionId)).id];

          const polls = yield* store.list({
            where: {
              sessionId: sessionIds,
              status: filter.status == null ? ["active", "closed"] : [filter.status],
            },
          });

          return yield* forStudent(viewer, polls);
        }),
        vote: Effect.fn("Polls.vote")(function* (viewer, id, response) {
          if (viewer.role !== "student") {
            return yield* new NotStudent();
          }

          const poll = yield* findPoll(id);

          yield* visibleSession(sessions, poll.sessionId).pipe(
            Effect.mapError(() => new PollNotFound()),
          );

          if (poll.status !== "active") {
            return yield* new PollNotActive();
          }

          if (!fitsPoll(poll, response)) {
            return yield* new InvalidResponse();
          }

          const responseId = yield* crypto.randomULID.pipe(Effect.orDie);

          yield* responses.upsert(
            { id: responseId, pollId: poll.id, userId: viewer.id, value: response },
            { target: ["pollId", "userId"], set: { value: response } },
          );
          yield* notifyPolls(poll);
          yield* changelog.drop({ type: "poll-opened", entityId: poll.id });

          const [voted] = yield* forStudent(viewer, [poll]);

          return voted ?? (yield* Effect.die("the voted poll was not read back"));
        }),
        listForTeacher: Effect.fn("Polls.listForTeacher")(function* (sessionId) {
          yield* existingSession(sessions, sessionId);

          return yield* forTeacher(yield* store.list({ where: { sessionId } }));
        }),
        create: Effect.fn("Polls.create")(function* (draft) {
          yield* existingSession(sessions, draft.sessionId);

          if (!fitsType(draft)) {
            return yield* new InvalidPollContent();
          }

          const id = yield* crypto.randomULID.pipe(Effect.orDie);
          const poll = yield* store.create({ ...draft, id, status: "draft" });

          return { ...poll, results: tally(poll, noResponses) };
        }),
        update: Effect.fn("Polls.update")(function* (id, change) {
          const poll = yield* findPoll(id);

          if (isContentChange(change) && poll.status !== "draft") {
            return yield* new PollNotDraft();
          }

          const next = change.status;

          if (
            next != null &&
            !transitions.some(([from, to]) => from === poll.status && to === next)
          ) {
            return yield* new InvalidTransition();
          }

          // The content a draft ends up with must still fit its type.
          if (
            !fitsType({
              type: poll.type,
              options: change.options ?? poll.options,
              scaleMinLabel: change.scaleMinLabel ?? poll.scaleMinLabel,
              scaleMaxLabel: change.scaleMaxLabel ?? poll.scaleMaxLabel,
            })
          ) {
            return yield* new InvalidPollContent();
          }

          const updated = yield* Effect.flatMap(store.update(id, change), (stored) =>
            Effect.fromOption(stored).pipe(Effect.mapError(() => new PollNotFound())),
          );

          if (next != null) {
            yield* notifyPolls(updated);
          }

          if (next === "active") {
            yield* changelog.record({
              sessionId: updated.sessionId,
              type: "poll-opened",
              entityId: id,
              name: updated.prompt,
            });
          }

          if (next === "closed") {
            yield* changelog.drop({ type: "poll-opened", entityId: id });
          }

          const [withResults] = yield* forTeacher([updated]);

          return withResults ?? (yield* Effect.die("the updated poll was not read back"));
        }),
        remove: Effect.fn("Polls.remove")(function* (id) {
          const poll = yield* findPoll(id);

          yield* store.remove(id);
          yield* notifyPolls(poll);
          yield* changelog.drop({ type: "poll-opened", entityId: id });
        }),
      });
    }),
  );
}

import type { PollResults, ResponseValue } from "@kurasu/contract/polls";

import type { ResponseCounts } from "./responses-store.ts";
import type { StoredPoll } from "./polls-store.ts";

const countsOf = (size: number, votes: ReadonlyArray<readonly [number, number]>) => {
  const counts = Array.from({ length: size }, () => 0);

  for (const [index, count] of votes) {
    counts[index] = (counts[index] ?? 0) + count;
  }

  return counts;
};

// The results of a poll from its counted votes, without saying who voted what:
// a count per option, per point of the scale (1 to 5) or per word, the most
// sent words first.
export const tally = (poll: StoredPoll, counts: ResponseCounts): PollResults => {
  const { count, values } = counts;

  if (poll.type === "choice") {
    const votes = values.flatMap(({ value, count: sent }) =>
      "choice" in value ? [[value.choice, sent] as const] : [],
    );

    return { count, choice: countsOf(poll.options?.length ?? 0, votes) };
  }

  if (poll.type === "scale") {
    const votes = values.flatMap(({ value, count: sent }) =>
      "scale" in value ? [[value.scale - 1, sent] as const] : [],
    );

    return { count, scale: countsOf(5, votes) };
  }

  return {
    count,
    words: counts.words.toSorted((a, b) => b.count - a.count || a.word.localeCompare(b.word)),
  };
};

// Whether a vote is of the poll's type and, for a choice, one of its options.
export const fitsPoll = (poll: StoredPoll, value: ResponseValue) => {
  if (poll.type === "choice") {
    return "choice" in value && value.choice < (poll.options?.length ?? 0);
  }

  return poll.type === "scale" ? "scale" in value : "words" in value;
};
