import { AdminPoll, PollOptions } from "@kurasu/contract/polls";
import { PollsStore, type StoredPoll } from "@kurasu/core/polls/polls-store";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";

import { repositoryOf } from "./repository.ts";
import { polls } from "./schema.ts";

const { results: _results, ...storedPollFields } = AdminPoll.fields;

// The content of the other poll type is null in the row and absent in the poll.
const decodeRow = Schema.decodeUnknownEffect(
  Schema.Struct({
    ...storedPollFields,
    options: Schema.NullOr(PollOptions),
    scaleMinLabel: Schema.NullOr(Schema.String),
    scaleMaxLabel: Schema.NullOr(Schema.String),
  }),
);

const toPoll = (row: typeof polls.$inferSelect): Effect.Effect<StoredPoll> =>
  decodeRow(row).pipe(
    Effect.orDie,
    Effect.map((poll) => ({
      ...poll,
      options: poll.options ?? undefined,
      scaleMinLabel: poll.scaleMinLabel ?? undefined,
      scaleMaxLabel: poll.scaleMaxLabel ?? undefined,
    })),
  );

export const D1Polls = Layer.effect(
  PollsStore,
  Effect.gen(function* () {
    const repository = yield* repositoryOf(polls, {
      decode: toPoll,
      deletedAt: polls.deletedAt,
    });

    return PollsStore.of({
      ...repository,
      create: (poll) =>
        repository.create({
          ...poll,
          options: poll.options ?? null,
          scaleMinLabel: poll.scaleMinLabel ?? null,
          scaleMaxLabel: poll.scaleMaxLabel ?? null,
        }),
    });
  }),
);

import { CurrentUser } from "@kurasu/contract/middleware";
import { Polls } from "@kurasu/core/polls/polls";
import * as Effect from "effect/Effect";
import { HttpApiBuilder } from "effect/http-api";

import { KurasuApi } from "@kurasu/contract/api";

export const PollsHandlers = HttpApiBuilder.group(KurasuApi, "polls", (handlers) =>
  handlers
    .handle("list", ({ query }) =>
      Effect.gen(function* () {
        const polls = yield* Polls;

        return yield* polls.listForStudent(yield* CurrentUser, query);
      }),
    )
    .handle("vote", ({ params, payload }) =>
      Effect.gen(function* () {
        const polls = yield* Polls;

        return yield* polls.vote(yield* CurrentUser, params.id, payload.myResponse);
      }),
    ),
);

export const AdminPollsHandlers = HttpApiBuilder.group(KurasuApi, "adminPolls", (handlers) =>
  handlers
    .handle("list", ({ query }) =>
      Effect.gen(function* () {
        const polls = yield* Polls;

        return yield* polls.listForTeacher(query.sessionId);
      }),
    )
    .handle("create", ({ payload }) =>
      Effect.gen(function* () {
        const polls = yield* Polls;

        return yield* polls.create(payload);
      }),
    )
    .handle("update", ({ params, payload }) =>
      Effect.gen(function* () {
        const polls = yield* Polls;

        return yield* polls.update(params.id, payload);
      }),
    )
    .handle("delete", ({ params }) =>
      Effect.gen(function* () {
        const polls = yield* Polls;

        yield* polls.remove(params.id);
      }),
    ),
);

import type { Poll, ResponseValue } from "@kurasu/contract/polls";
import * as Predicate from "effect/Predicate";
import { useState } from "react";

import { Button } from "../../ui/Button.tsx";
import { InlineError } from "../../ui/InlineError.tsx";
import { Spinner } from "../../ui/Spinner.tsx";
import { PollResults } from "./PollResults.tsx";
import { scaleLabelsOf } from "./scale-labels.ts";
import { useVote } from "./useVote.ts";
import { mergeWords } from "./words.ts";

interface Props {
  poll: Poll;
  onClosed?: () => void;
}

const scaleValues = [1, 2, 3, 4, 5];

const textLink = "text-sm text-coal underline";

export const VoteForm = ({ poll, onClosed }: Props) => {
  const [changing, setChanging] = useState(false);
  const [draft, setDraft] = useState("");

  const vote = useVote({
    onSuccess: () => {
      setChanging(false);
      setDraft("");
    },
    onError: (error) => (Predicate.isTagged(error, "PollNotActive") ? onClosed?.() : undefined),
  });

  const mine = poll.myResponse;
  const editing = mine == null || changing;
  const words = mine != null && "words" in mine ? mine.words : [];
  const send = (myResponse: ResponseValue) => vote.mutate({ pollId: poll.id, myResponse });
  const sending = vote.isPending ? vote.variables.myResponse : null;

  if (poll.type === "words") {
    return (
      <div>
        {editing ? (
          <form
            className="mt-2.5 flex gap-2"
            onSubmit={(event) => {
              event.preventDefault();
              send({ words: mergeWords(words, draft) });
            }}
          >
            <input
              value={draft}
              onChange={(event) => setDraft(event.target.value)}
              placeholder={
                mine == null
                  ? "Tus palabras, separadas por coma"
                  : "Más palabras, separadas por coma"
              }
              aria-label={mine == null ? "Tus palabras" : "Más palabras"}
              disabled={vote.isPending}
              className="min-w-0 flex-1 rounded-full border-2 border-coal bg-paper px-3.5 py-[7px] text-coal"
            />
            <Button
              variant="main"
              type="submit"
              disabled={mergeWords([], draft).length === 0}
              pending={vote.isPending}
              pendingLabel="Enviando…"
              className="px-3.5 py-1.5 text-sm"
            >
              Enviar
            </Button>
          </form>
        ) : null}
        {vote.isError && !Predicate.isTagged(vote.error, "PollNotActive") ? (
          <InlineError className="mt-2">
            No se pudo enviar tu respuesta. Probá de nuevo.
          </InlineError>
        ) : null}
        {words.length === 0 ? null : (
          <div className="mt-2 text-[13px] opacity-70">Tus palabras: {words.join(", ")}</div>
        )}
        {editing || poll.results == null ? null : (
          <PollResults type="words" results={poll.results} mine={mine} />
        )}
        {mine == null ? null : (
          <div className="mt-2.5 flex justify-end">
            <button
              type="button"
              className={textLink}
              disabled={vote.isPending}
              onClick={() => setChanging(!changing)}
            >
              {changing ? "Cancelar" : "Sumar más palabras"}
            </button>
          </div>
        )}
      </div>
    );
  }

  if (!editing) {
    return (
      <div>
        {poll.results == null ? null : (
          <PollResults
            type={poll.type}
            results={poll.results}
            options={poll.options}
            scaleLabels={scaleLabelsOf(poll)}
            mine={mine}
          />
        )}
        <div className="mt-2.5 flex justify-end">
          <button type="button" className={textLink} onClick={() => setChanging(true)}>
            Cambiar mi voto
          </button>
        </div>
      </div>
    );
