import type { PollResults as Results, PollType, ResponseValue } from "@kurasu/contract/polls";

import { percent } from "./percent.ts";

interface Props {
  type: PollType;
  results: Results;
  options?: ReadonlyArray<string> | undefined;
  scaleLabels?: readonly [string, string] | undefined;
  mine?: ResponseValue | null | undefined;
  showCounts?: boolean;
}

const scaleValues = [1, 2, 3, 4, 5];

export const PollResults = ({
  type,
  results,
  options,
  scaleLabels,
  mine,
  showCounts = false,
}: Props) => {
  if (type === "choice") {
    const counts = results.choice ?? [];
    const total = counts.reduce((sum, count) => sum + count, 0);
    const chosen = mine != null && "choice" in mine ? mine.choice : null;

    return (
      <ul aria-label="Resultados" className="mt-3 flex flex-col gap-2">
        {(options ?? []).map((option, index) => (
          <li
            key={option}
            aria-current={index === chosen}
            className={`relative flex justify-between gap-2.5 overflow-hidden rounded-xl border-2 bg-paper px-3.5 py-[9px] text-coal max-[600px]:px-3 max-[600px]:py-2.5 ${
              index === chosen ? "border-coal" : "border-sand"
            }`}
          >
            <i
              className="absolute inset-y-0 left-0 bg-peach opacity-60"
              style={{ width: `${percent(counts[index] ?? 0, total)}%` }}
            />
            <span className="relative">
              {index === chosen ? "✓ " : ""}
              {option}
            </span>
            <span className="relative">{percent(counts[index] ?? 0, total)}%</span>
          </li>
        ))}
      </ul>
    );
  }

  if (type === "scale") {
    const counts = results.scale ?? [0, 0, 0, 0, 0];
    const highest = Math.max(1, ...counts);
    const chosen = mine != null && "scale" in mine ? mine.scale : null;

    return (
      <div>
        <ul aria-label="Resultados" className="mt-2.5 grid grid-cols-5 items-end gap-2">
          {scaleValues.map((value, index) => (
            <li key={value} aria-current={value === chosen}>
              <div
                className={`flex items-end justify-center rounded-t-lg pb-0.5 text-xs ${
                  value === chosen ? "bg-coal text-white" : "bg-lilac"
                }`}
                style={{ height: `${10 + ((counts[index] ?? 0) / highest) * 60}px` }}
              >
                {counts[index] ?? 0}
              </div>
              <div className="text-center text-[13px]">{value}</div>
            </li>
          ))}
        </ul>
        {scaleLabels == null ? null : (
          <div className="mt-1 flex justify-between gap-2.5 text-xs opacity-70">
            <span>{scaleLabels[0]}</span>
            <span>{scaleLabels[1]}</span>
          </div>
        )}
      </div>
    );
  }

  const words = results.words ?? [];
  const highest = Math.max(1, ...words.map((entry) => entry.count));
  const own = mine != null && "words" in mine ? mine.words : [];

  return words.length === 0 ? (
    <div className="mt-2 text-sm opacity-70">Todavía sin palabras.</div>
  ) : (
    <ul
      aria-label="Resultados"
      className="flex flex-wrap items-baseline justify-center gap-x-3.5 gap-y-1 px-1.5 py-2.5"
    >
      {words.map((entry) => (
        <li
          key={entry.word}
          title={`${entry.word}: ${entry.count}`}
          aria-current={own.includes(entry.word)}
          className={`font-display leading-[1.1] font-bold ${own.includes(entry.word) ? "underline" : ""}`}
          style={{
            fontSize: `${14 + (entry.count / highest) * 24}px`,
            opacity: 0.55 + (entry.count / highest) * 0.45,
          }}
        >
          {entry.word}
          {showCounts ? (
            <span className="ml-1 align-super font-sans text-xs font-normal opacity-70">
              {entry.count}
            </span>
          ) : null}
        </li>
      ))}
    </ul>
  );
};

import type { AdminPoll, Poll, ResponseValue } from "@kurasu/contract/polls";
import type { ReactNode } from "react";

import { Icon } from "../../ui/Icon.tsx";
import { PollResults } from "./PollResults.tsx";
import { scaleLabelsOf } from "./scale-labels.ts";

interface Props {
  poll: Poll | AdminPoll;
  meta: ReactNode;
  showResults: boolean;
  mine?: ResponseValue | null;
  status?: ReactNode;
  body?: ReactNode;
  actions?: ReactNode;
  open?: boolean;
  onToggle?: () => void;
  bordered?: boolean;
  showCounts?: boolean;
}

// A poll as both sides show it. A card with `onToggle` folds: its header is
// the button, and the rest shows only while it is open.
export const PollCard = ({
  poll,
  meta,
  showResults,
  mine,
  status,
  body,
  actions,
  open = true,
  onToggle,
  bordered = false,
  showCounts = false,
}: Props) => {
  const header = (
    <span className="min-w-0 flex-1">
      {status}
      <span className="flex items-start gap-2 font-display font-medium">
        <Icon name="chart-bar" size={18} className="mt-0.5" />
        <span>{poll.prompt}</span>
      </span>
      <span className="mt-0.5 block text-[13px] opacity-70">{meta}</span>
    </span>
  );

  return (
    <article
      aria-label={poll.prompt}
      className={`skeleton-block paper px-[18px] py-4 max-[600px]:p-3.5 ${bordered ? "border-[1.5px] border-sand" : ""}`}
    >
      {onToggle == null ? (
        header
      ) : (
        <button
          type="button"
          aria-expanded={open}
          onClick={onToggle}
          className="flex w-full items-center justify-between gap-3 text-left text-coal"
        >
          {header}
          <Icon name={open ? "chevron-up" : "chevron-down"} size={18} />
        </button>
      )}
      {open ? body : null}
      {open && showResults && poll.results != null ? (
        <PollResults
          type={poll.type}
          results={poll.results}
          options={poll.options}
          scaleLabels={scaleLabelsOf(poll)}
          mine={mine}
          showCounts={showCounts}
        />
      ) : null}
      {open ? actions : null}
    </article>
  );
};

import { ResponseValue } from "@kurasu/contract/polls";
import { Ulid } from "@kurasu/contract/ulid";
import { ResponsesStore } from "@kurasu/core/polls/responses-store";
import { sql } from "drizzle-orm";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";

import { Database } from "./database.ts";
import { repositoryOf } from "./repository.ts";
import { responses } from "./schema.ts";

const decodeResponse = Schema.decodeUnknownEffect(
  Schema.Struct({ id: Ulid, pollId: Ulid, userId: Ulid, value: ResponseValue }),
);

// A row of the counts: a choice or scale vote with how many sent it (`value`),
// the votes of a words poll (neither), or a word with how many students sent it
// (`word`).
const decodeCountRows = Schema.decodeUnknownEffect(
  Schema.Array(
    Schema.Struct({
      pollId: Ulid,
      value: Schema.NullOr(Schema.fromJsonString(ResponseValue)),
      word: Schema.NullOr(Schema.String),
      count: Schema.Int,
    }),
  ),
);

export const D1Responses = Layer.effect(
  ResponsesStore,
  Effect.gen(function* () {
    const { db } = yield* Database;

    const repository = yield* repositoryOf(responses, {
      decode: (row) => decodeResponse(row).pipe(Effect.orDie),
    });

    // The poll ids go as one JSON array, so the query binds two parameters
    // however many polls it counts.
    const countRows = (pollIds: string) =>
      db.all(sql`
        select ${responses.pollId} as pollId,
          case when json_type(${responses.value}, '$.words') is null then ${responses.value} end as value,
          null as word,
          count(*) as count
        from ${responses}
        where ${responses.pollId} in (select value from json_each(${pollIds}))
        group by 1, 2
        union all
        select ${responses.pollId} as pollId,
          null,
          words.value as word,
          count(distinct ${responses.userId}) as count
        from ${responses}, json_each(${responses.value}, '$.words') as words
        where ${responses.pollId} in (select value from json_each(${pollIds}))
        group by 1, 3
      `);

    return ResponsesStore.of({
      list: repository.list,
      upsert: repository.upsert,
      counts: (pollIds) =>
        Effect.gen(function* () {
          if (pollIds.length === 0) {
            return new Map();
          }

          const rows = yield* countRows(JSON.stringify(pollIds)).pipe(
            Effect.flatMap(decodeCountRows),
            Effect.orDie,
          );

          return new Map(
            [...Map.groupBy(rows, (row) => row.pollId)].map(([pollId, pollRows]) => [
              pollId,
              {
                count: pollRows.reduce((sum, row) => (row.word == null ? sum + row.count : sum), 0),
                values: pollRows.flatMap(({ value, word, count }) =>
                  value == null || word != null ? [] : [{ value, count }],
                ),
                words: pollRows.flatMap(({ word, count }) =>
                  word == null ? [] : [{ word, count }],
                ),
              },
            ]),
          );
        }),
    });
  }),
);

