import type { MockDefinition } from '@canvas/MockShape'
import { GREEN, HAND, INK, LINE, MUTED, PAPER, RED, sketchBorder } from '@canvas/kit/theme'

type State = 'empty' | 'sending' | 'answered' | 'editing' | 'error' | 'closed'

interface Props {
  state: State
  pick: number | null
  text: string
}

const EMOJIS = ['😞', '😕', '😐', '🙂', '😄']
const CARD = '#CCC4F0'
const PICKED = '#F8D0A0'

const Emoji = ({ value, index, pick, dim }: { value: string; index: number; pick: number | null; dim: boolean }) => {
  const on = pick === index + 1

  return (
    <div
      style={{
        ...sketchBorder(on ? INK : LINE),
        borderRadius: 12,
        flex: 1,
        textAlign: 'center',
        fontSize: 22,
        lineHeight: '1.35',
        background: on ? PICKED : PAPER,
        opacity: dim ? 0.5 : 1,
      }}
    >
      {value}
    </div>
  )
}

const Scale = ({ pick, dim }: { pick: number | null; dim: boolean }) => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginTop: 12 }}>
    <div style={{ display: 'flex', gap: 8 }}>
      {EMOJIS.map((value, index) => (
        <Emoji key={value} value={value} index={index} pick={pick} dim={dim} />
      ))}
    </div>
    <div style={{ display: 'flex', fontSize: 11, color: MUTED }}>
      <span style={{ flex: 1 }}>No me gustó</span>
      <span style={{ flex: 1, textAlign: 'center' }}>Más o menos</span>
      <span style={{ flex: 1, textAlign: 'right' }}>Me gustó</span>
    </div>
  </div>
)

const Field = ({ text, dim }: { text: string; dim: boolean }) => (
  <div
    style={{
      ...sketchBorder(LINE),
      borderRadius: 12,
      padding: '8px 10px',
      marginTop: 10,
      minHeight: 46,
      fontSize: 14,
      color: text === '' ? MUTED : INK,
      opacity: dim ? 0.5 : 1,
    }}
  >
    {text === '' ? '¿Qué te pareció la sesión? (opcional)' : text}
  </div>
)

const Button = ({ label, dim }: { label: string; dim: boolean }) => (
  <span
    style={{
      ...sketchBorder(),
      borderRadius: 999,
      padding: '4px 14px',
      fontSize: 13,
      background: INK,
      color: PAPER,
      whiteSpace: 'nowrap',
      opacity: dim ? 0.55 : 1,
    }}
  >
    {label}
  </span>
)

const Link = ({ label }: { label: string }) => (
  <span style={{ fontSize: 12, textDecoration: 'underline' }}>{label}</span>
)

const Saved = ({ pick, text }: { pick: number | null; text: string }) => (
  <div style={{ ...sketchBorder(LINE), borderRadius: 12, padding: '8px 10px', marginTop: 8, display: 'flex', gap: 8, alignItems: 'flex-start' }}>
    <span style={{ fontSize: 22, lineHeight: 1.2 }}>{EMOJIS[(pick ?? 4) - 1]}</span>
    <span style={{ fontSize: 13, lineHeight: 1.35 }}>{text === '' ? 'Sin comentario.' : text}</span>
  </div>
)

const Body = ({ state, pick, text }: Props) => {
  if (state === 'answered' || state === 'closed') {
    const closed = state === 'closed'

    return (
      <div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start', marginTop: 12 }}>
          <span style={{ width: 26, height: 26, borderRadius: '50%', background: '#B4E8CC', display: 'grid', placeItems: 'center', flex: 'none', fontSize: 14 }}>✓</span>
          <div>
            <div style={{ fontSize: 14, fontWeight: 700 }}>{closed ? 'La encuesta se cerró.' : 'Gracias, ya nos llegó tu feedback.'}</div>
            <div style={{ fontSize: 11, color: MUTED }}>{closed ? 'Esta encuesta no acepta cambios.' : 'Podés cambiarlo cuando quieras.'}</div>
          </div>
        </div>
        <Saved pick={pick} text={text} />
        {closed ? null : (
          <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 8 }}>
            <Link label="Cambiar mi respuesta" />
          </div>
        )}
      </div>
    )
  }

  return (
    <div>
      <Scale pick={pick} dim={state === 'sending'} />
      <Field text={text} dim={state === 'sending'} />
      {state === 'error' ? <div style={{ marginTop: 8, fontSize: 12, color: RED }}>No se pudo enviar tu feedback. Probá de nuevo.</div> : null}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, marginTop: 10 }}>
        <span style={{ fontSize: 11, color: MUTED }}>El texto es opcional.</span>
        <Button label={state === 'sending' ? '◌ Enviando…' : 'Enviar feedback'} dim={state === 'sending' || pick == null} />
      </div>
      {state === 'editing' ? (
        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 6 }}>
          <Link label="Cancelar" />
        </div>
      ) : null}
    </div>
  )
}

const meta: Record<State, string> = {
  empty: 'Encuesta de feedback · se puede cambiar',
  sending: 'Encuesta de feedback · se puede cambiar',
  answered: 'Encuesta de feedback · se puede cambiar',
  editing: 'Encuesta de feedback · se puede cambiar',
  error: 'Encuesta de feedback · se puede cambiar',
  closed: 'Encuesta de feedback · cerrada',
}

const Screen = ({ state, pick, text }: Props) => (
  <div data-root style={{ fontFamily: HAND, color: INK, background: CARD, borderRadius: 18, padding: 14, display: 'flex', flexDirection: 'column', gap: 8 }}>
    <div style={{ fontSize: 12, fontWeight: 700, letterSpacing: '0.04em', textTransform: 'uppercase', opacity: 0.6 }}>Sesión 2 · Planificar y revisar</div>
    <div style={{ background: PAPER, borderRadius: 14, padding: 12 }}>
      <div style={{ display: 'flex', gap: 6, alignItems: 'flex-start', fontSize: 15, fontWeight: 700 }}>
        <span>💬</span>
        <span>¿Cómo estuvo la sesión de hoy?</span>
      </div>
      <div style={{ fontSize: 11, color: MUTED, marginTop: 2 }}>{meta[state]}</div>
      <Body state={state} pick={pick} text={text} />
    </div>
  </div>
)

export const mockup: MockDefinition<Props> = {
  width: 480,
  defaults: { state: 'empty', pick: null, text: '' },
  render: (props) => <Screen {...props} />,
}

