      ? `${p.options.map((o, i) => `<div class="opt"><input value="${o}" placeholder="Opción ${i + 1}"><button class="iconbtn" data-delopt="${p.id}|${i}" title="Quitar">${ic('x', 16)}</button></div>`).join('')}<button class="add" data-addopt="${p.id}">${ic('plus', 16)} Agregar opción</button>`
      : p.type === 'scale'
        ? `<div class="ends"><label>Qué significa el 1<input value="${p.ends[0]}"></label><label>Qué significa el 5<input value="${p.ends[1]}"></label></div>`
        : '';

    return `<input value="${p.question}" placeholder="Pregunta">${extra}<div class="actions">${delPoll(p)}<button class="btn dark" data-activate="${p.id}">Activar</button></div>`;
  }

  const res = p.type === 'choice'
    ? p.options.map((o, i) => `<div class="row"><i style="width:${p.results[i]}%"></i><span>${o}</span><span>${p.results[i]}%</span></div>`).join('')
    : p.type === 'scale' ? `<div class="note">Todavía sin respuestas · 1 = ${p.ends[0]}, 5 = ${p.ends[1]}</div>` : '<div class="note">Todavía sin palabras.</div>';

  return `<div class="note">${p.total ?? 0} respuestas</div>${res}<div class="actions">${delPoll(p)}${p.state === 'active' ? `<button class="btn" data-close="${p.id}">Cerrar</button>` : ''}</div>`;
};

