  const bottom = (n) => canvas.bounds(n).y + canvas.bounds(n).h
  const questions = { b1: ['q1','q2','q3'], b2: ['q4','q5'], b3: ['q6'], b4: ['q7'], b5: ['q8'], b6: [] }

  const content = (n) => {
    const ys = [bottom(n + '-leaves'), bottom(n + '-prose'), ...questions[n].map(bottom)]
    if (questions[n].length > 0) ys.push(bottom(n + '-note'))
    return Math.max(...ys)
  }

  const columns = [['b1','b2','b3'], ['b4','b5','b6']]
  const out = {}

  for (const col of columns) {
    for (let i = 0; i < col.length; i++) {
      const n = col[i]
      const a = canvas.bounds(n)
      const h = content(n) - a.y + 40
      await canvas.resize(n, { h })
      out[n] = Math.round(h)
      const next = col[i + 1]
      if (next != null) await canvas.move(next, { y: a.y + h + 90 })
    }
  }

  return JSON.stringify(out)
})()
EOF

