     3	type PollContent = Pick<PollDraft, "type" | "options" | "scaleMinLabel" | "scaleMaxLabel">;
     4	
     5	// A choice poll carries its options and a scale poll its labels; the fields of
     6	// the other types stay empty.
     7	export const fitsType = (poll: PollContent) => {
     8	  const hasLabels = poll.scaleMinLabel != null || poll.scaleMaxLabel != null;
     9	
    10	  if (poll.type === "choice") {
    11	    return poll.options != null && !hasLabels;
    12	  }
    13	
    14	  return poll.options == null && (poll.type === "scale" || !hasLabels);
