     1	import type { PollResults, ResponseValue } from "@kurasu/contract/polls";
     2	
     3	import type { ResponseCounts } from "./responses-store.ts";
     4	import type { StoredPoll } from "./polls-store.ts";
     5	
     6	const countsOf = (size: number, votes: ReadonlyArray<readonly [number, number]>) => {
     7	  const counts = Array.from({ length: size }, () => 0);
     8	
     9	  for (const [index, count] of votes) {
    10	    counts[index] = (counts[index] ?? 0) + count;
    11	  }
    12	
    13	  return counts;
    14	};
    15	
    16	// The results of a poll from its counted votes, without saying who voted what:
    17	// a count per option, per point of the scale (1 to 5) or per word, the most
    18	// sent words first.
    19	export const tally = (poll: StoredPoll, counts: ResponseCounts): PollResults => {
    20	  const { count, values } = counts;
    21	
    22	  if (poll.type === "choice") {
    23	    const votes = values.flatMap(({ value, count: sent }) =>
    24	      "choice" in value ? [[value.choice, sent] as const] : [],
    25	    );
    26	
    27	    return { count, choice: countsOf(poll.options?.length ?? 0, votes) };
    28	  }
    29	
    30	  if (poll.type === "scale") {
    31	    const votes = values.flatMap(({ value, count: sent }) =>
    32	      "scale" in value ? [[value.scale - 1, sent] as const] : [],
    33	    );
    34	
    35	    return { count, scale: countsOf(5, votes) };
    36	  }
    37	
    38	  return {
    39	    count,
    40	    words: counts.words.toSorted((a, b) => b.count - a.count || a.word.localeCompare(b.word)),
    41	  };
    42	};
    43	
    44	// Whether a vote is of the poll's type and, for a choice, one of its options.
    45	export const fitsPoll = (poll: StoredPoll, value: ResponseValue) => {
    46	  if (poll.type === "choice") {
    47	    return "choice" in value && value.choice < (poll.options?.length ?? 0);
    48	  }
    49	
    50	  return poll.type === "scale" ? "scale" in value : "words" in value;
    51	};


