     3	
     4	export interface PollContent {
     5	  prompt: string;
     6	  options: ReadonlyArray<string>;
     7	  scaleMinLabel: string;
     8	  scaleMaxLabel: string;
     9	}
    10	
    11	export const emptyContent: PollContent = {
    12	  prompt: "",
    13	  options: ["", ""],
    14	  scaleMinLabel: "",
    15	  scaleMaxLabel: "",
    16	};
    17	
    18	export const contentOf = (poll: AdminPoll): PollContent => ({
    19	  prompt: poll.prompt,
    20	  options: poll.options ?? ["", ""],
    21	  scaleMinLabel: poll.scaleMinLabel ?? "",
    22	  scaleMaxLabel: poll.scaleMaxLabel ?? "",
    23	});
    24	
    25	export const isComplete = (type: PollType, content: PollContent) =>
    26	  content.prompt.trim() !== "" &&
    27	  (type !== "choice" ||
    28	    (content.options.length <= maxOptions &&
    29	      content.options.every((option) => option.trim() !== "")));
    30	
    31	// What a type of poll carries: a choice poll its options, a scale poll the
    32	// meaning of its ends, a word cloud only its prompt.
    33	export const fieldsOf = (type: PollType, content: PollContent) => {
    34	  if (type === "choice") {
    35	    return {
    36	      prompt: content.prompt.trim(),
    37	      options: content.options.map((option) => option.trim()),
    38	    };
    39	  }
    40	
    41	  if (type === "scale") {
    42	    return {
    43	      prompt: content.prompt.trim(),
    44	      scaleMinLabel: content.scaleMinLabel.trim(),
    45	      scaleMaxLabel: content.scaleMaxLabel.trim(),
    46	    };
    47	  }
    48	
    49	  return { prompt: content.prompt.trim() };
    50	};


