// Lays out one part: an area with its items one under another, each item placed at its own x offset.
const part = async (name, { x, y, w, label }, items) => {
  await c.area(name, { x, y, w, h: 200, label }, 0)
  let top = y + 70
  let rowBottom = top

  for (const item of items) {
    const ix = x + (item.dx ?? 40)
    const iy = item.sameRow ? item.rowTop : top
    const opts = { x: ix, y: iy, into: name }

    if (item.type === 'mermaid') {
      await c.mermaid(item.name, { x: ix, y: iy, source: item.source }, 0)
      await wait(900)
      await c.fit(item.name)
    } else if (item.type === 'mock') {
      await c.mock(item.name, { ...opts, w: item.w, kind: item.kind, data: item.data }, 0)
    } else if (item.type === 'text') {
      await c.text(item.name, { ...opts, w: item.w, text: item.text, mono: item.mono ?? false }, 0)
    } else if (item.type === 'card') {
      await c.card(item.name, { ...opts, w: item.w, text: item.text, color: item.color, fill: item.fill, mono: item.mono }, 0)
    } else if (item.type === 'note') {
      await c.note(item.name, { x: ix, y: iy, w: item.w, text: item.text }, 0)
    }

    const b = c.bounds(item.name)
    rowBottom = Math.max(rowBottom, b.y + b.h)

    if (!item.keepRow) {
      top = rowBottom + (item.gap ?? 40)
      rowBottom = top
    }

    item.placedTop = iy
  }

  await c.fit(name)
  return c.bounds(name)
}

